const brand = Color(0xFF7B1E2B);
Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await LocalStore.init(); runApp(const DarwinApp()); }

class Api {
  static String base = 'http://10.0.2.2:5000'; // Android emulator -> Windows host. Change for a physical phone/LAN/Tailscale.
  static String? token;
  static Future<dynamic> get(String path) async { final r=await http.get(Uri.parse('$base$path'),headers:_headers()).timeout(const Duration(seconds:12)); return _decode(r); }
  static Future<dynamic> post(String path,Map<String,dynamic> body) async { final r=await http.post(Uri.parse('$base$path'),headers:_headers(),body:jsonEncode(body)).timeout(const Duration(seconds:12));return _decode(r); }
  static Map<String,String> _headers()=>{'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};
  static dynamic _decode(http.Response r){final data=r.body.isEmpty?{}:jsonDecode(r.body);if(r.statusCode<200||r.statusCode>=300)throw Exception(data is Map?data['message']??'Request failed (${r.statusCode})':'Request failed (${r.statusCode})');return data;}
}

class LocalStore {
 static Database? db;
 static Future<void> init() async { final root=await getDatabasesPath();db=await openDatabase(p.join(root,'darwin_mobile.db'),version:1,onCreate:(d,v)async{await d.execute('CREATE TABLE drafts(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, synced INTEGER NOT NULL DEFAULT 0)');}); }
 static Future<void> saveDraft(String title,Map<String,dynamic> data) async {await db!.insert('drafts',{'title':title,'payload':jsonEncode(data),'created_at':DateTime.now().toIso8601String(),'synced':0});}
 static Future<List<Map<String,Object?>>> drafts() async => db!.query('drafts',orderBy:'id DESC');
}

